    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Potencia suministrada por la fuente (PCC)",
        "pregunta": "Calcule la potencia continua entregada por la fuente $P_{CC} = V_{CC} \\cdot I_{CQ}$ (en Watts).",
        "pistas": [
          "Pista 1: Multiplique la tensión de alimentación total por la corriente de reposo.",
          "Pista 2: $P_{CC} = 24\\text{ V} \\cdot 0.75\\text{ A} = 18.0\\text{ W}$."
        ],
        "explicacion": "$P_{CC} = V_{CC} \\cdot I_{CQ} = 24\\text{ V} \\cdot 0.75\\text{ A} = 18.0\\text{ W}$. En Clase A resistivo, esta potencia se absorbe continuamente de la fuente con o sin señal.",
        "tipoRespuesta": "numerica",
        "unidad": "W",
        "solucion": 18,
        "valorEsperado": 18,
        "tolerancia": 0.05,
        "simbolo": "P_{CC}",
        "explicacionPaso": "$P_{CC} = 24 \\times 0.75 = 18.0\\text{ W}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Potencia máxima en la carga (PL,max)",
        "pregunta": "Determine la potencia máxima de alterna disipada en la carga $P_{L,max} = \\frac{\\hat{V}_o \\hat{I}_o}{2}$ (en Watts).",
        "pistas": [
          "Pista 1: La amplitud pico máxima sin recorte es $\\hat{V}_o = V_{CEQ} = 12\\text{ V}$ y $\\hat{I}_o = I_{CQ} = 0.75\\text{ A}$.",
          "Pista 2: $P_{L,max} = \\frac{12\\text{ V} \\cdot 0.75\\text{ A}}{2} = 4.50\\text{ W}$."
        ],
        "explicacion": "$P_{L,max} = \\frac{V_{CEQ} \\cdot I_{CQ}}{2} = \\frac{12\\text{ V} \\cdot 0.75\\text{ A}}{2} = 4.50\\text{ W}$. Note que el rendimiento es $\\eta = \\frac{4.5}{18} = 0.25$ ($25\\%$).",
        "tipoRespuesta": "numerica",
        "unidad": "W",
        "solucion": 4.5,
        "valorEsperado": 4.5,
        "tolerancia": 0.05,
        "simbolo": "P_{L,max}",
        "explicacionPaso": "$P_{L,max} = \\frac{12 \\times 0.75}{2} = 4.50\\text{ W}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Potencia disipada en reposo por el transistor (PD,Q)",
        "pregunta": "Determine la potencia que debe disipar el transistor en reposo $P_{D,Q} = V_{CEQ} \\cdot I_{CQ}$ (en Watts).",
        "pistas": [
          "Pista 1: En ausencia de señal, el transistor soporta toda la tensión $V_{CEQ}$ con la corriente $I_{CQ}$.",
          "Pista 2: $P_{D,Q} = 12\\text{ V} \\cdot 0.75\\text{ A} = 9.0\\text{ W}$."
        ],
        "explicacion": "$P_{D,Q} = V_{CEQ} \\cdot I_{CQ} = 12\\text{ V} \\cdot 0.75\\text{ A} = 9.00\\text{ W}$. Ésta es la condición más exigente de disipación para el transistor; al ingresar señal, parte de esa potencia se desvía a la carga.",
        "tipoRespuesta": "numerica",
        "unidad": "W",
        "solucion": 9,
        "valorEsperado": 9,
        "tolerancia": 0.05,
        "simbolo": "P_{D,Q}",
        "explicacionPaso": "$P_{D,Q} = 12 \\times 0.75 = 9.00\\text{ W}$."
      }
    ]
