    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Corriente de salida Widlar (IC)",
        "pregunta": "Determine la corriente de salida de colector $I_C$ que satisface $I_C R_E = V_T \\ln(I_{ref}/I_C)$ (en $\\mu\\text{A}$).",
        "pistas": [
          "Pista 1: Para $I_C \\approx 20\\,\\mu\\text{A}$: $\\ln(1000/20) = \\ln(50) = 3.912$.",
          "Pista 2: $V_T \\ln(50) = 25\\text{ mV} \\cdot 3.912 = 97.8\\text{ mV}$.",
          "Pista 3: $I_C R_E = 20\\,\\mu\\text{A} \\cdot 5\\text{ k}\\Omega = 100\\text{ mV}$. La solución exacta por iteración converge a $19.2\\,\\mu\\text{A}$."
        ],
        "explicacion": "Resolviendo la ecuación trascendente $I_C (5.0\\text{ k}\\Omega) = 25\\text{ mV} \\ln(1\\text{ mA}/I_C)$ se obtiene $I_C \\approx 19.2\\,\\mu\\text{A}$ ($0.0192\\text{ mA}$).",
        "tipoRespuesta": "numerica",
        "unidad": "μA",
        "solucion": 19.2,
        "valorEsperado": 19.2,
        "tolerancia": 0.08,
        "simbolo": "I_C",
        "explicacionPaso": "$I_C \\approx 19.2\\,\\mu\\text{A}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Salto de tensión base-emisor",
        "pregunta": "Calcule la diferencia de tensión entre junturas $\\Delta V_{BE} = I_C R_E$ (en mV).",
        "pistas": [
          "Pista 1: $\\Delta V_{BE} = 19.2\\,\\mu\\text{A} \\cdot 5.0\\text{ k}\\Omega$.",
          "Pista 2: $19.2 \\cdot 10^{-6} \\cdot 5000 = 0.096\\text{ V} = 96.0\\text{ mV}$."
        ],
        "explicacion": "$\\Delta V_{BE} = V_{BE1} - V_{BE2} = I_C R_E = 19.2\\,\\mu\\text{A} \\cdot 5.0\\text{ k}\\Omega = 96.0\\text{ mV}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mV",
        "solucion": 96,
        "valorEsperado": 96,
        "tolerancia": 0.05,
        "simbolo": "\\Delta V_{BE}",
        "explicacionPaso": "$\\Delta V_{BE} = 19.2\\,\\mu\\text{A} \\times 5.0\\text{ k}\\Omega = 96.0\\text{ mV}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Comparación con resistencia directa equivalente",
        "pregunta": "Calcule el valor de resistencia necesario para obtener $19.2\\,\\mu\\text{A}$ directamente desde $V_{CC}=15\\text{ V}$ con $V_R = 14.3\\text{ V}$ (en kΩ).",
        "pistas": [
          "Pista 1: $R = \\frac{14.3\\text{ V}}{19.2\\,\\mu\\text{A}} = \\frac{14.3}{0.0192\\text{ mA}} \\approx 744.8\\text{ k}\\Omega$."
        ],
        "explicacion": "$R_{directa} = \\frac{14.3\\text{ V}}{19.2\\,\\mu\\text{A}} \\approx 745\\text{ k}\\Omega$. La fuente Widlar sustituye un resistor gigante de $745\\text{ k}\\Omega$ ocupando apenas $R_E = 5\\text{ k}\\Omega$, ahorrando enorme área de silicio.",
        "tipoRespuesta": "numerica",
        "unidad": "kΩ",
        "solucion": 745,
        "valorEsperado": 745,
        "tolerancia": 0.05,
        "simbolo": "R_{directa}",
        "explicacionPaso": "$R_{directa} = 14.3 / 0.0192 = 745.0\\text{ k}\\Omega$."
      }
    ]
