    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Factor de desensibilización (D)",
        "pregunta": "Calcule el factor de lazo $D = 1 + g_m R_E$ (adimensional).",
        "pistas": [
          "Pista 1: $g_m R_E = 40\\text{ mS} \\cdot 220\\,\\Omega = 0.040 \\cdot 220 = 8.80$.",
          "Pista 2: $D = 1 + 8.80 = 9.80$."
        ],
        "explicacion": "$D = 1 + g_m R_E = 1 + (0.040\\text{ S} \\cdot 220\\,\\Omega) = 1 + 8.80 = 9.80$.",
        "tipoRespuesta": "numerica",
        "unidad": "",
        "solucion": 9.8,
        "valorEsperado": 9.8,
        "tolerancia": 0.05,
        "simbolo": "D",
        "explicacionPaso": "$D = 1 + 40\\text{ mS} \\times 220\\,\\Omega = 9.80$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Transconductancia a lazo cerrado (Gmf)",
        "pregunta": "Calcule la transconductancia efectiva $G_{mf} = \\frac{g_m}{D}$ (en mS).",
        "pistas": [
          "Pista 1: Divida $g_m = 40\\text{ mS}$ por $D = 9.80$.",
          "Pista 2: $40 / 9.80 \\approx 4.08\\text{ mS}$."
        ],
        "explicacion": "$G_{mf} = \\frac{g_m}{1 + g_m R_E} = \\frac{40\\text{ mS}}{9.80} \\approx 4.08\\text{ mS}$. Note que si $g_m R_E \\gg 1$, $G_{mf} \\approx 1/R_E = 1/220 = 4.54\\text{ mS}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mS",
        "solucion": 4.08,
        "valorEsperado": 4.08,
        "tolerancia": 0.05,
        "simbolo": "G_{mf}",
        "explicacionPaso": "$G_{mf} = 40 / 9.80 = 4.08\\text{ mS}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Ganancia de tensión resultante (Av)",
        "pregunta": "Determine la ganancia de tensión $A_v = -G_{mf} R_C$ (en V/V).",
        "pistas": [
          "Pista 1: Multiplique la transconductancia efectiva por la resistencia de colector $R_C = 3.3\\text{ k}\\Omega$.",
          "Pista 2: $A_v = -4.08\\text{ mS} \\cdot 3300\\,\\Omega = -13.46\\text{ V/V}$."
        ],
        "explicacion": "$A_v = -G_{mf} R_C = -(4.082\\text{ mS}) \\cdot (3.3\\text{ k}\\Omega) = -13.47\\text{ V/V}$. La realimentación linealiza la respuesta frente a dispersiones del punto Q a costa de moderar la ganancia.",
        "tipoRespuesta": "numerica",
        "unidad": "V/V",
        "solucion": -13.47,
        "valorEsperado": -13.47,
        "tolerancia": 0.05,
        "simbolo": "A_v",
        "explicacionPaso": "$A_v = -4.082 \\times 3.3 = -13.47\\text{ V/V}$."
      }
    ]
